    fn route_request(&self, mut req: Request<B>) -> RouterFuture<B> {
        if req.extensions().get::<OriginalUri>().is_none() {
            let original_uri = OriginalUri(req.uri().clone());
            req.extensions_mut().insert(original_uri);
        }

        let path = req.uri().path().to_owned();

        match self.node.at(&path) {
            Ok(match_) => self.call_route(match_, req),
            Err(err) => {
                if err.tsr() {
                    let new_path: Cow<str> = if let Some(without_tsr) = path.strip_suffix('/') {
                        Cow::Borrowed(without_tsr)
                    } else {
                        Cow::Owned(format!("{}/", path))
                    };

                    let uri = req.uri();
                    let path_and_query = if let Some(path_and_query) = uri.path_and_query() {
                        let new_path = if new_path.starts_with('/') {
                            Cow::Borrowed(new_path.as_ref())
                        } else {
                            Cow::Owned(format!("/{}", new_path))
                        };

                        if let Some(query) = path_and_query.query() {
                            Some(
                                format!("{}?{}", new_path, query)
                                    .parse::<http::uri::PathAndQuery>()
                                    .unwrap(),
                            )
                        } else {
                            Some(new_path.parse().unwrap())
                        }
                    } else {
                        None
                    };

                    let mut parts = http::uri::Parts::default();
                    parts.scheme = uri.scheme().cloned();
                    parts.authority = uri.authority().cloned();
                    parts.path_and_query = path_and_query;
                    let redirect_to = Uri::from_parts(parts).unwrap();

                    let res = Redirect::with_status_code(
                        StatusCode::MOVED_PERMANENTLY,
                        redirect_to,
                    )
                    .into_response();
                    RouterFuture::from_response(res)
                } else {
                    match &self.fallback {
                        Fallback::Default(inner) => {
                            RouterFuture::from_future(inner.clone().call(req))
                        }
                        Fallback::Custom(inner) => {
                            RouterFuture::from_future(inner.clone().call(req))
                        }
                    }
                }
            }
        }
    }

    fn panic_on_matchit_error(&self, err: matchit::InsertError) {
        if self.nested_at_root {
            panic!(
                "Invalid route: {}. Note that `nest(\"/\", _)` conflicts with all routes. Use `Router::fallback` instead",
                err,
            );
        } else {
            panic!("Invalid route: {}", err);
        }
    }
}

